scenarios.example_code:
import { registerPurpose } from '@projexlight/sdk-consent';
await registerPurpose({
  tenant_id, name: 'marketing-emails',
  description: 'We send product update + offer emails',
  legal_basis: 'consent', // gdpr-art-6
  default_expiry_days: 365,
});

import { grantConsent } from '@projexlight/sdk-consent';
const receipt = await grantConsent({
  tenant_id, subject_persona_id, purpose_id,
  channel: 'portal-checkbox',
  // expires_at auto-filled from purpose.default_expiry_days
});

import { checkConsent } from '@projexlight/sdk-consent';
const ok = await checkConsent({
  tenant_id, subject_persona_id, purpose_id: 'marketing-emails',
});
if (!ok) throw new Error('No active consent receipt');

